    haloText(g, 's', (rx + mid) / 2 + 14, (baseY + apexY) / 2 - 12, 21, 'middle');
  }
  haloText(g, 'D', mid + 9, (apexY + baseY) / 2 - 3, 21, 'start');
  fractionL(g, (lx + mid) / 2 - 5, baseY + 23, 20, 'middle');
  haloText(g, 'L', (rx + mid) / 2, baseY + 22, 21, 'middle');
  haloText(g, 's = √(D² + L²)', mid + 46, apexY - 38, 22, 'start');
