  draw.clear();

  var root = draw.group();
  drawShuttle(root);
  drawBeam(root);

  var astronautOpacity = 1, earthOpacity = 1, triOpacity = 1;
  if (state.emphasisActive) {
    if (state.observerFrame === 'Astronaut frame') {
      earthOpacity = 0.32;
      triOpacity = 0.44;
    } else {
      astronautOpacity = 0.38;
    }
