    state: { observerFrame: 'Earth frame', shuttleSpeed: 0.6, pulseEvent: 'ending' }
  },
  {
    title: 'Increase the shuttle speed',
    narration: "Drag the speed slider upward: the cabin snapshots spread apart, L grows, and the purple diagonal sides of the triangle lengthen. Because light speed is the same for both observers, the longer Earth-frame path requires a larger elapsed time Δt.",
    state: { observerFrame: 'Earth frame', shuttleSpeed: 0.85, pulseEvent: 'ending' }
  },
  {
    title: 'Connect the picture to the triangle',
    narration: "The reduced triangle shows the whole argument: each half-trip has vertical leg D, horizontal leg L = vΔt/2, and hypotenuse s. Since s = √(D² + L²), any nonzero horizontal motion makes s greater than D.",
    state: { observerFrame: 'Earth frame', shuttleSpeed: 0.75, pulseEvent: 'mirror reflection' }
  }
];

var teal = '#13a6a6';
var purple = '#7a4fa0';
var yellow = '#ffd12a';
var paleCyan = '#9ed9de';

function haloText(parent, txt, x, y, size, anchor, color) {
  var t = parent.text(txt)
    .font({ family: 'Arial, Helvetica, sans-serif', size: size || 18, anchor: anchor || 'start', leading: 1.08 })
    .fill(color || '#111');
  t.attr({
    x: x,
    y: y,
    'paint-order': 'stroke',
    stroke: '#fff',
    'stroke-width': Math.max(3, (size || 18) * 0.20),
    'stroke-linejoin': 'round'
  });
  return t;
}

function arrow(parent, x1, y1, x2, y2, color, width, opacity) {
  var g = parent.group().opacity(opacity == null ? 1 : opacity);
  var w = width || 3;
  g.line(x1, y1, x2, y2).stroke({ color: color, width: w, linecap: 'round', linejoin: 'round' });
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var len = 10 + w * 1.45, wid = 8 + w * 0.70;
  var p1 = [x2, y2];
  var p2 = [x2 - len * Math.cos(ang) + wid * Math.sin(ang) / 2, y2 - len * Math.sin(ang) - wid * Math.cos(ang) / 2];
  var p3 = [x2 - len * Math.cos(ang) - wid * Math.sin(ang) / 2, y2 - len * Math.sin(ang) + wid * Math.cos(ang) / 2];
  g.polygon([p1, p2, p3].map(function (p) { return p.join(','); }).join(' ')).fill(color).stroke('none');
  return g;
}

function bracket(parent, x1, y1, x2, y2, label, vertical, size, labelDx, labelDy) {
  var g = parent.group();
  var tick = vertical ? 12 : 13;
  g.line(x1, y1, x2, y2).stroke({ color: '#111', width: 1.75, linecap: 'round' });
  if (vertical) {
    g.line(x1 - tick, y1, x1 + tick, y1).stroke({ color: '#111', width: 1.55 });
    g.line(x2 - tick, y2, x2 + tick, y2).stroke({ color: '#111', width: 1.55 });
    if (label) haloText(g, label, x1 + (labelDx == null ? 18 : labelDx), (y1 + y2) / 2 - 8 + (labelDy || 0), size || 20, 'start');
  } else {
    g.line(x1, y1 - tick, x1, y1 + tick).stroke({ color: '#111', width: 1.55 });
    g.line(x2, y2 - tick, x2, y2 + tick).stroke({ color: '#111', width: 1.55 });
    if (label) haloText(g, label, (x1 + x2) / 2 + (labelDx || 0), y1 + 21 + (labelDy || 0), size || 19, 'middle');
  }
  return g;
}

function fractionL(parent, x, y, size, anchor) {
  var g = parent.group();
  var s = size || 18;
  var prefixX = anchor === 'start' ? x : x - 42;
  haloText(g, 'L =', prefixX, y, s, 'start');
  var cx = prefixX + 79;
  haloText(g, 'v Δt', cx, y - 13, s * 0.88, 'middle');
  g.line(cx - 26, y + 1, cx + 26, y + 1).stroke({ color: '#111', width: 1.45 });
  haloText(g, '2', cx, y + 9, s * 0.88, 'middle');
  return g;
}

function burst(parent, x, y, r) {
  var g = parent.group();
  for (var i = 0; i < 12; i++) {
    var a = i * Math.PI / 6;
    g.line(x + Math.cos(a) * r * 0.42, y + Math.sin(a) * r * 0.42, x + Math.cos(a) * r, y + Math.sin(a) * r)
      .stroke({ color: '#ffb000', width: Math.max(1.1, r * 0.16), linecap: 'round' });
  }
  g.circle(r * 1.05).center(x, y).fill(yellow).stroke({ color: '#ff9c00', width: 1.2 });
  return g;
}

function clock(parent, x, y, r, label) {
  var g = parent.group();
  g.circle(2 * r).center(x, y).fill('#fff').stroke({ color: '#111', width: 2 });
  for (var i = 0; i < 12; i++) {
    var a = -Math.PI / 2 + i * Math.PI / 6;
    g.line(x + Math.cos(a) * r * 0.78, y + Math.sin(a) * r * 0.78, x + Math.cos(a) * r * 0.93, y + Math.sin(a) * r * 0.93)
      .stroke({ color: '#333', width: 1.2 });
  }
  g.line(x, y, x, y - r * 0.62).stroke({ color: teal, width: 3, linecap: 'round' });
  g.line(x, y, x + r * 0.45, y - r * 0.24).stroke({ color: teal, width: 3, linecap: 'round' });
  haloText(g, label, x + r + 8, y - 2, 21, 'start');
  return g;
}

function astronaut(parent, x, y, s) {
  var g = parent.group();
  g.ellipse(21 * s, 26 * s).center(x, y - 43 * s).fill('#2f3036');
  g.circle(15 * s).center(x, y - 49 * s).fill('#f4b28d').stroke({ color: '#444', width: 1 });
  g.path('M ' + (x - 23 * s) + ' ' + (y - 29 * s) + ' C ' + (x - 40 * s) + ' ' + (y + 13 * s) + ' ' + (x - 23 * s) + ' ' + (y + 49 * s) + ' L ' + (x + 22 * s) + ' ' + (y + 44 * s) + ' C ' + (x + 37 * s) + ' ' + (y + 7 * s) + ' ' + (x + 22 * s) + ' ' + (y - 31 * s) + ' Z')
    .fill('#f06d42').stroke({ color: '#555', width: 1 });
  g.line(x - 16 * s, y + 47 * s, x - 35 * s, y + 85 * s).stroke({ color: '#758b8b', width: 13 * s, linecap: 'round' });
  g.line(x + 15 * s, y + 46 * s, x + 29 * s, y + 84 * s).stroke({ color: '#758b8b', width: 13 * s, linecap: 'round' });
  g.line(x - 23 * s, y - 8 * s, x - 53 * s, y + 15 * s).stroke({ color: '#f06d42', width: 12 * s, linecap: 'round' });
  g.line(x + 23 * s, y - 7 * s, x + 55 * s, y + 8 * s).stroke({ color: '#f06d42', width: 12 * s, linecap: 'round' });
  g.rect(24 * s, 32 * s).center(x, y + 7 * s).fill('#f7cf52').stroke({ color: '#777', width: 1 });
  g.line(x - 26 * s, y + 12 * s, x + 22 * s, y + 22 * s).stroke({ color: '#2187bd', width: 5 * s, linecap: 'round' });
  return g;
}

function earthObserver(parent, x, y, s) {
  var g = parent.group();
  g.circle(11 * s).center(x, y - 66 * s).fill('#b87838').stroke({ color: '#555', width: 1 });
  g.rect(24 * s, 55 * s).center(x, y - 30 * s).fill('#87a964').stroke({ color: '#555', width: 1 });
  g.line(x - 7 * s, y - 2 * s, x - 20 * s, y + 45 * s).stroke({ color: '#607b86', width: 9 * s, linecap: 'round' });
  g.line(x + 7 * s, y - 2 * s, x + 18 * s, y + 45 * s).stroke({ color: '#607b86', width: 9 * s, linecap: 'round' });
  g.line(x - 14 * s, y - 42 * s, x - 35 * s, y - 15 * s).stroke({ color: '#87a964', width: 8 * s, linecap: 'round' });
  g.line(x + 14 * s, y - 42 * s, x + 34 * s, y - 16 * s).stroke({ color: '#87a964', width: 8 * s, linecap: 'round' });
  return g;
}

function apparatus(parent, x, ySource, yMirror, scale, showArrows) {
  var g = parent.group();
  var s = scale || 1;
  g.rect(40 * s, 8 * s).center(x, yMirror).fill('#b8dfe3').stroke({ color: '#111', width: 1.5 * s });
  g.rect(16 * s, 39 * s).center(x + 9 * s, ySource - 18 * s).fill('#b8dfe3').stroke({ color: '#111', width: 1.2 * s });
  g.circle(20 * s).center(x + 58 * s, ySource - 2 * s).fill('#fff').stroke({ color: '#111', width: 1.4 * s, dasharray: '2,2' });
  burst(g, x - 8 * s, ySource - 6 * s, 11 * s);
  if (showArrows) {
    arrow(g, x - 4 * s, ySource - 18 * s, x - 4 * s, yMirror + 13 * s, teal, 3.2 * s);
    arrow(g, x + 14 * s, yMirror + 13 * s, x + 14 * s, ySource - 18 * s, teal, 3.2 * s);
  }
  return g;
}

function drawShuttle(parent) {
  var shuttle = parent.group();
  shuttle.path('M55 28 L345 28 Q405 42 430 75 Q417 99 348 103 L64 112 L40 82 Z')
    .fill('#f4f4f4').stroke({ color: '#111', width: 2 });
  shuttle.path('M322 48 L415 76 L430 75 Q418 99 345 103 L285 92 Z').fill('#262626').stroke({ color: '#111', width: 1.5 });
  shuttle.path('M66 111 L190 91 L365 98 L348 113 Z').fill('#333').stroke({ color: '#111', width: 1 });
  shuttle.path('M58 28 L15 5 L0 5 L34 75 L76 75 Z').fill('#f7f7f7').stroke({ color: '#111', width: 2.5 });
  shuttle.path('M22 12 L52 58 L30 62 L5 8 Z').fill('#fff').stroke({ color: '#111', width: 1.5 });
  shuttle.path('M45 80 C22 74 11 91 10 120 L39 108 Z').fill('#222').stroke({ color: '#111', width: 1.5 });
  for (var e = 0; e < 4; e++) shuttle.path('M23 ' + (84 + e * 8) + ' C8 ' + (90 + e * 8) + ' 4 ' + (97 + e * 8) + ' 5 ' + (104 + e * 8)).fill('none').stroke({ color: '#111', width: 2 });
  shuttle.rect(100, 25).move(108, 29).fill('#f8f8f8').stroke({ color: '#111', width: 1 });
  shuttle.rect(35, 19).move(213, 34).fill('#b8dfe3').stroke({ color: '#111', width: 1 });
  astronaut(shuttle, 230, 78, 0.28);
  shuttle.on('mousemove', function (e) { showTooltip('The light clock rides inside the shuttle.', e); }).on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Moving light clock', 'The source, mirror, receiver, and astronaut are at rest together inside the shuttle. This is the frame that measures the proper time Δτ.'); });
  shuttle.css('cursor', 'pointer');
  return shuttle;
}

function drawBeam(parent) {
  var beam = parent.group();
  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#eef8f9', 0.42);
    add.stop(1, '#cfe9ec', 0.72);
  }).from(0, 0).to(0, 1);
  beam.polygon('142,128 306,128 408,222 8,222')
    .fill(grad)
    .stroke({ color: '#c7d9dc', width: 1, opacity: 0.45 });
  beam.line(142, 128, 8, 222).stroke({ color: '#d2e1e3', width: 2, opacity: 0.75 });
  beam.line(306, 128, 408, 222).stroke({ color: '#d2e1e3', width: 2, opacity: 0.75 });
}

function drawAstronautPanel(parent, opacity) {
  var g = parent.group().opacity(opacity == null ? 1 : opacity);
  var cabinGrad = draw.gradient('linear', function (add) {
    add.stop(0, '#eef6f7');
    add.stop(1, '#c8d1d0');
  }).from(0, 0).to(1, 1);
  g.rect(410, 286).move(5, 222).radius(24).fill(cabinGrad).stroke({ color: paleCyan, width: 5 });
  astronaut(g, 198, 340, 0.9);
  haloText(g, 'Astronaut', 24, 313, 20, 'start');
  g.path('M113 315 C132 304 142 306 153 311').fill('none').stroke({ color: '#111', width: 2.4 });
  arrow(g, 150, 311, 166, 311, '#111', 2.4);
  clock(g, 172, 405, 22, 'Δτ');
  apparatus(g, 282, 378, 259, 1.0, true);
  haloText(g, 'Mirror', 249, 235, 20, 'start');
  haloText(g, 'Light\nsource', 226, 432, 20, 'start');
  haloText(g, 'Receiver', 300, 432, 20, 'start');
  g.path('M246 421 C235 399 245 391 264 387').fill('none').stroke({ color: '#111', width: 2.2 });
  g.path('M326 424 C326 399 316 390 300 386').fill('none').stroke({ color: '#111', width: 2.2 });
  bracket(g, 347, 259, 347, 378, 'D', true, 21);
  haloText(g, '(a)', 215, 548, 20, 'middle');
  g.on('mousemove', function (e) { showTooltip('Astronaut frame: vertical round trip, total light distance 2D.', e); }).on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Astronaut frame', 'In the shuttle frame the clock is at rest, so the light travels straight up to the mirror and straight down to the receiver. The elapsed time is the proper time Δτ.'); });
  g.css('cursor', 'pointer');
  return g;
}

function miniApparatus(parent, sourceX, ySource, yMirror, scale) {
  var s = scale || 1;
  var g = parent.group();
  g.rect(32 * s, 7 * s).center(sourceX + 34 * s, yMirror).fill('#b8dfe3').stroke({ color: '#111', width: 1.1 * s });
  g.rect(13 * s, 28 * s).center(sourceX + 42 * s, ySource - 12 * s).fill('#b8dfe3').stroke({ color: '#111', width: 0.9 * s });
  g.circle(16 * s).center(sourceX + 76 * s, ySource).fill('#fff').stroke({ color: '#111', width: 1.1 * s, dasharray: '2,2' });
  burst(g, sourceX, ySource - 2 * s, 8.5 * s);
  return g;
}

function drawCabinSnapshot(parent, left, y, kind) {
  var g = parent.group();
  var cw = 116, ch = 142;
  g.rect(cw, ch).move(left, y).radius(17).fill('#d7dcdb').opacity(0.98)
    .stroke({ color: '#111', width: 2, dasharray: '8,6' });
  g.rect(35, 8).move(left + 18, y + 15).fill('#b8dfe3').stroke({ color: '#111', width: 1 });
  var srcX = kind === 'right' ? left + 32 : left + 24;
  if (kind === 'middle') srcX = left + 28;
  miniApparatus(g, srcX, y + 126, y + 23, 0.64);
  return g;
}

function highlight(parent, x, y, label) {
  var g = parent.group();
  g.circle(32).center(x, y).fill('#ffe35a').opacity(0.24).stroke({ color: '#ffb000', width: 2 });
  g.circle(12).center(x, y).fill('#ffcf27').stroke({ color: '#e58a00', width: 2 });
  g.on('mousemove', function (e) { showTooltip(label, e); }).on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Same event', label + ' This physical event is shared by both frames; what changes is the path assigned to the light between events.'); });
  g.css('cursor', 'pointer');
  return g;
}

function drawEarthPanel(parent, opacity) {
  var g = parent.group().opacity(opacity == null ? 1 : opacity);
  var v = state.shuttleSpeed;
  var L = v * 260;
  var startX = Math.min(520, 940 - 2 * L);
  if (L < 1) startX = 690;
  var yCab = 205;
  var yMirror = yCab + 23;
  var ySource = yCab + 126;
  var startPt = { x: startX, y: ySource - 2 };
  var apexPt = { x: startX + L, y: yMirror };
  var endPt = { x: startX + 2 * L, y: ySource - 2 };

  var left1 = startPt.x - 24;
  var left2 = apexPt.x - 58;
  var left3 = endPt.x - 54;
  drawCabinSnapshot(g, left1, yCab, 'left');
  drawCabinSnapshot(g, left2, yCab, 'middle');
  drawCabinSnapshot(g, left3, yCab, 'right');

  if (L > 8) {
    arrow(g, startPt.x, startPt.y, apexPt.x, apexPt.y, purple, 2.6);
    arrow(g, apexPt.x, apexPt.y, endPt.x, endPt.y, purple, 2.6);
  } else {
    g.line(startPt.x - 5, ySource - 8, startPt.x - 5, yMirror + 8).stroke({ color: purple, width: 2.6, linecap: 'round' });
    g.line(startPt.x + 8, yMirror + 8, startPt.x + 8, ySource - 8).stroke({ color: purple, width: 2.6, linecap: 'round' });
  }
  if (L > 35) {
    haloText(g, 's', (startPt.x + apexPt.x) / 2 - 10, (startPt.y + apexPt.y) / 2 - 18, 20, 'middle');
    haloText(g, 's', (apexPt.x + endPt.x) / 2 + 11, (apexPt.y + endPt.y) / 2 - 18, 20, 'middle');
  }

  bracket(g, left3 + 92, yMirror, left3 + 92, ySource - 2, 'D', true, 20, -2);
  var by = ySource + 43;
  if (L > 35) {
    bracket(g, startPt.x, by, apexPt.x, by, '', false, 18);
    fractionL(g, (startPt.x + apexPt.x) / 2 - 8, by + 10, 18, 'middle');
    bracket(g, apexPt.x, by, endPt.x, by, 'L', false, 19, 0, -2);
  }
  haloText(g, 'Beginning\nevent', startPt.x - 10, ySource + 69, 19, 'middle');
  haloText(g, 'Ending\nevent', endPt.x + 5, ySource + 69, 19, 'middle');

  g.polygon('548,475 914,475 960,540 490,540').fill('#d8d1c8').opacity(0.82).stroke('none');
  earthObserver(g, 690, 514, 0.86);
  haloText(g, 'Observer\non Earth', 540, 489, 20, 'start');
  g.path('M626 497 C642 487 653 491 663 498').fill('none').stroke({ color: '#111', width: 2.4 });
  arrow(g, 659, 498, 674, 494, '#111', 2.4);
  clock(g, 735, 489, 21, 'Δt');
  haloText(g, '(b)', 735, 562, 20, 'middle');

  g.on('mousemove', function (e) { showTooltip('Earth frame: the same emission, reflection, and reception events occur while the shuttle moves sideways.', e); }).on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Earth frame', 'From Earth, the shuttle moves while the pulse is in flight. The same light ray therefore connects the same events along two longer diagonal segments.'); });
  g.css('cursor', 'pointer');

  return { group: g, startPt: startPt, apexPt: apexPt, endPt: endPt, L: L };
}

function drawTrianglePanel(parent, opacity) {
  var g = parent.group().opacity(opacity == null ? 1 : opacity);
  var v = state.shuttleSpeed;
  var Ltri = v * 260;
  var mid = 500, baseY = 745, apexY = 632;
  var lx = mid - Ltri, rx = mid + Ltri;

  g.line(lx, baseY, rx, baseY).stroke({ color: '#111', width: 2 });
  g.line(mid, apexY, mid, baseY).stroke({ color: '#111', width: 2 });
  if (Ltri > 8) {
    arrow(g, lx, baseY, mid - 4, apexY + 4, purple, 2.45);
    arrow(g, mid + 4, apexY + 4, rx, baseY, purple, 2.45);
  } else {
    g.line(mid - 5, baseY, mid - 5, apexY).stroke({ color: purple, width: 2.45 });
    g.line(mid + 5, apexY, mid + 5, baseY).stroke({ color: purple, width: 2.45 });
  }

  if (Ltri > 35) {
    haloText(g, 's', (lx + mid) / 2 - 13, (baseY + apexY) / 2 - 14, 21, 'middle');
    haloText(g, 's', (rx + mid) / 2 + 13, (baseY + apexY) / 2 - 14, 21, 'middle');
  }
  haloText(g, 'D', mid + 10, (apexY + baseY) / 2 - 4, 21, 'start');
  fractionL(g, (lx + mid) / 2 - 5, baseY + 25, 20, 'middle');
  haloText(g, 'L', (rx + mid) / 2, baseY + 23, 21, 'middle');
  haloText(g, 's = √(D² + L²)', mid + 46, apexY - 34, 22, 'start');
  haloText(g, '(c)', mid, 818, 20, 'middle');

  g.on('mousemove', function (e) { showTooltip('Right-triangle geometry: for each half-trip, s² = D² + L².', e); }).on('mouseleave', hideTooltip)
    .on('click', function () { showPopup('Triangle argument', 'Each Earth-frame half-trip has vertical leg D and horizontal leg L = vΔt/2. The hypotenuse s is longer than D whenever L is nonzero, so a light pulse moving at speed c requires a longer Earth-frame time.'); });
  g.css('cursor', 'pointer');

  return { group: g, left: { x: lx, y: baseY }, apex: { x: mid, y: apexY }, right: { x: rx, y: baseY } };
}

function drawEventHighlights(root, earthGeom, triGeom) {
  if (!state.showHighlights) return;
  var evt = state.pulseEvent;
  if (evt === 'beginning') {
    highlight(root, 274, 372, 'Beginning event: the light leaves the source.');
    highlight(root, earthGeom.startPt.x, earthGeom.startPt.y, 'Beginning event: emission from the light source.');
    highlight(root, triGeom.left.x, triGeom.left.y, 'Beginning event on the triangle.');
  } else if (evt === 'mirror reflection') {
    highlight(root, 282, 259, 'Mirror reflection event: the pulse reaches the mirror.');
    highlight(root, earthGeom.apexPt.x, earthGeom.apexPt.y, 'Mirror reflection event.');
    highlight(root, triGeom.apex.x, triGeom.apex.y, 'Mirror reflection event at the triangle apex.');
  } else {
    highlight(root, 300, 372, 'Ending event: the pulse reaches the receiver.');
    highlight(root, earthGeom.endPt.x, earthGeom.endPt.y, 'Ending event: reception by the receiver.');
    highlight(root, triGeom.right.x, triGeom.right.y, 'Ending event on the triangle.');
  }
}

function render() {
  draw.clear();

  var root = draw.group();
  drawShuttle(root);
  drawBeam(root);

  var astronautOpacity = 1, earthOpacity = 1, triOpacity = 1;
  if (state.emphasisActive) {
    if (state.observerFrame === 'Astronaut frame') {
      earthOpacity = 0.36;
      triOpacity = 0.46;
    } else {
      astronautOpacity = 0.40;
    }
  }

  drawAstronautPanel(root, astronautOpacity);
  var earthGeom = drawEarthPanel(root, earthOpacity);
  var triGeom = drawTrianglePanel(root, triOpacity);
  drawEventHighlights(root, earthGeom, triGeom);

  syncUI();
}

function syncUI() {
  var cb = document.getElementById('observerFrameInput');
  var frameVal = document.getElementById('observerFrameVal');
  var sl = document.getElementById('shuttleSpeedInput');
  var out = document.getElementById('shuttleSpeedVal');
  var ev = document.getElementById('eventLabel');
  var stepLabel = document.getElementById('stepLabel');
  var narr = document.getElementById('demoNarration');

  if (cb) cb.checked = state.observerFrame === 'Earth frame';
  if (frameVal) frameVal.textContent = state.observerFrame;
  if (sl) sl.value = state.shuttleSpeed;
  if (out) out.value = state.shuttleSpeed.toFixed(2);
  if (ev) ev.textContent = 'event: ' + state.pulseEvent + (state.showHighlights ? '' : ' (markers hidden)');
  if (stepLabel) stepLabel.textContent = (state.step + 1) + '/' + demoSteps.length + ' ' + demoSteps[state.step].title;
  if (narr) narr.textContent = demoSteps[state.step].narration;
}

function toggle_observerFrame(on) {
  state.emphasisActive = true;
  state.observerFrame = on ? 'Earth frame' : 'Astronaut frame';
  render();
}

function update_shuttleSpeed(v) {
  state.emphasisActive = true;
  state.shuttleSpeed = Math.max(0, Math.min(0.9, v));
  render();
}

function trigger_pulseEvent() {
  state.emphasisActive = true;
  state.showHighlights = true;
  var i = eventOrder.indexOf(state.pulseEvent);
  state.pulseEvent = eventOrder[(i + 1) % eventOrder.length];
  render();
}

function applyStep(n, activate) {
  state.step = (n + demoSteps.length) % demoSteps.length;
  var s = demoSteps[state.step].state;
  state.observerFrame = s.observerFrame;
  state.shuttleSpeed = s.shuttleSpeed;
  state.pulseEvent = s.pulseEvent;
